exercise.solution:
fn handle_ping(name: &str) -> Result<String, String> {
    if name.trim().is_empty() {
        return Err(String::from("name required"));
    }
    Ok(format!("pong, {name}"))
}

fn main() {
    println!("{:?}", handle_ping("vue"));
    println!("{:?}", handle_ping(""));
}
